/** O texto de ANTES deste conserto (LF). Lança se um bloco deste conserto não estiver lá exatamente uma vez. */
export function semLinkLojas1510(rel, text) {
  let s = String(text).replace(/\r\n/g, '\n')
  const hunks = DESFAZ[rel]
  if (!hunks) return s
  for (const h of hunks) {
    const now = h.now.join('\n')
    const parts = s.split(now)
    if (parts.length !== 2) throw new Error('semLinkLojas1510: ' + rel + ' mudou fora deste conserto (' + (parts.length - 1) + 'x: ' + now.slice(0, 60) + ')')
    s = parts.join(h.before.join('\n'))
  }
  return s
}
export const LINK_LOJAS_1510_ARQUIVOS = Object.keys(DESFAZ)
